CREATE TABLE organizacion (id BIGSERIAL PRIMARY KEY, nombre VARCHAR(120) NOT NULL UNIQUE, fecha_creacion TIMESTAMPTZ NOT NULL, activa BOOLEAN NOT NULL);
CREATE TABLE servidor_autogestionado (id BIGSERIAL PRIMARY KEY, nombre VARCHAR(120) NOT NULL, direccion_red VARCHAR(255), clave_publica_servidor TEXT NOT NULL, activo BOOLEAN NOT NULL, organizacion_id BIGINT NOT NULL REFERENCES organizacion(id));
CREATE TABLE usuario (id BIGSERIAL PRIMARY KEY, nombre_usuario VARCHAR(80) NOT NULL UNIQUE, nombre_completo VARCHAR(160) NOT NULL, rol VARCHAR(30) NOT NULL, activo BOOLEAN NOT NULL, fecha_registro TIMESTAMPTZ NOT NULL, organizacion_id BIGINT NOT NULL REFERENCES organizacion(id));
CREATE TABLE dispositivo (id BIGSERIAL PRIMARY KEY, identificador_dispositivo VARCHAR(160) NOT NULL UNIQUE, nombre_dispositivo VARCHAR(120) NOT NULL, clave_publica_dispositivo TEXT NOT NULL, clave_publica_servidor TEXT NOT NULL, activo BOOLEAN NOT NULL, usuario_id BIGINT REFERENCES usuario(id));
CREATE TABLE solicitud_vinculacion (id BIGSERIAL PRIMARY KEY, nombre_usuario_solicitado VARCHAR(80) NOT NULL, nombre_dispositivo VARCHAR(120) NOT NULL, identificador_dispositivo VARCHAR(160) NOT NULL, clave_publica_dispositivo TEXT NOT NULL, fecha_solicitud TIMESTAMPTZ NOT NULL, estado VARCHAR(15) NOT NULL, organizacion_id BIGINT NOT NULL REFERENCES organizacion(id));
CREATE TABLE vinculacion_dispositivo (id BIGSERIAL PRIMARY KEY, usuario_id BIGINT NOT NULL REFERENCES usuario(id), dispositivo_id BIGINT NOT NULL REFERENCES dispositivo(id), solicitud_vinculacion_id BIGINT NOT NULL UNIQUE REFERENCES solicitud_vinculacion(id), fecha_aprobacion TIMESTAMPTZ NOT NULL, activa BOOLEAN NOT NULL);
CREATE TABLE equipo (id BIGSERIAL PRIMARY KEY, nombre VARCHAR(120) NOT NULL, fecha_creacion TIMESTAMPTZ NOT NULL, creador_id BIGINT NOT NULL REFERENCES usuario(id), organizacion_id BIGINT NOT NULL REFERENCES organizacion(id), activo BOOLEAN NOT NULL);
CREATE TABLE membresia_equipo (id BIGSERIAL PRIMARY KEY, usuario_id BIGINT NOT NULL REFERENCES usuario(id), equipo_id BIGINT NOT NULL REFERENCES equipo(id), fecha_ingreso TIMESTAMPTZ NOT NULL, activa BOOLEAN NOT NULL, UNIQUE(usuario_id, equipo_id));
CREATE TABLE tarea (id BIGSERIAL PRIMARY KEY, titulo VARCHAR(180) NOT NULL, descripcion TEXT, fecha_creacion TIMESTAMPTZ NOT NULL, fecha_vencimiento TIMESTAMPTZ, estado VARCHAR(20) NOT NULL, equipo_id BIGINT NOT NULL REFERENCES equipo(id), creador_id BIGINT NOT NULL REFERENCES usuario(id), activa BOOLEAN NOT NULL);
CREATE TABLE asignacion (id BIGSERIAL PRIMARY KEY, tarea_id BIGINT NOT NULL REFERENCES tarea(id), usuario_asignado_id BIGINT NOT NULL REFERENCES usuario(id), fecha_asignacion TIMESTAMPTZ NOT NULL, UNIQUE(tarea_id, usuario_asignado_id));
CREATE TABLE recordatorio (id BIGSERIAL PRIMARY KEY, tarea_id BIGINT NOT NULL REFERENCES tarea(id), usuario_id BIGINT NOT NULL REFERENCES usuario(id), fecha_hora TIMESTAMPTZ NOT NULL, activo BOOLEAN NOT NULL);